def correct_bracketing(brackets: str) -> bool:
    """ 
    Returns True if every opening bracket in the input string has a corresponding closing bracket.
    """
    # Mapping of opening and closing brackets
    bracket_map = {'(': ')', '[': ']', '{': '}'}

    # Stack to keep track of the opening brackets
    stack = []

    for char in brackets:
        if char in bracket_map:
            # If the character is an opening bracket, push it onto the stack
            stack.append(char)
        else:
            # If the character is a closing bracket, check if it matches the last opening bracket on the stack
            if not stack:
                return False
            last_char = stack.pop()
            if bracket_map[last_char] != char:
                return False

    # If all opening brackets have a corresponding closing bracket, return True
    return not stack

