import numpy as np

def max_fill(grid, capacity):
    m, n = len(grid), len(grid[0])
    buckets = np.zeros((m, n), dtype=int)

    # Initialize the first well with capacity
    for j in range(1, n):
        if grid[0][j-1] == 1:
            buckets[0][j] = capacity

    # Fill the first well
    for j in range(1, n):
        if grid[0][j-1] == 1:
            buckets[0][j] = buckets[0][j-1] + capacity

    # Fill the remaining wells
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j-1] == 1:
                buckets[i][j] = min(buckets[i-1][j], buckets[i][j-1]) + capacity
            elif buckets[i-1][j] >= buckets[i][j-1]:
                buckets[i][j] = buckets[i-1][j] + capacity

    # Calculate the result
    result = 0
    for j in range(n):
        if grid[m-1][j] == 1:
            result += buckets[m-1][j]

    return result

