        return []

    tri = []
    a, b, c = 0, 1, 1

    if n == 1:
        tri = [3]
        return tri

    for i in range(2, n+1):
        if i % 2 == 1:
            c = a + b + tri[i-1]
        else:
            a, b, c = b, c, a + b + b

        tri.append(c)

